from __future__ import annotations
from abc_creative_gold_v5_101_200_support import make_spec, register_craft
FACTS={
"Alphabet Blocks":"Blocks carry letters or pictures on faces; stacking adds spatial play while letter faces support recognition.",
"Blocks":"Separate solid pieces can stack, line up, balance, or build; stability depends on base width and center of mass.",
"Crayon":"Wax drawing stick adds mark-making to play; it belongs on suitable paper, not toys, walls, or mouths.",
"Dominoes":"Flat tiles can be matched by markings or stood in chains; game rules and toppling play are different activities.",
"Etch-a-Sketch":"Classic mechanical drawing toy uses two knobs to move a stylus horizontally and vertically behind a screen.",
"Frisbee":"Flying disc glides after a spinning throw; outdoor space and distance from people or roads matter.",
"Gyroscope":"Spinning rotor tends to resist changes to its orientation through angular momentum; toy versions demonstrate rotation.",
"Hoop":"Circular ring supports rolling, tossing, stepping, or waist-spinning games depending size and setting.",
"Inflatable Ball":"Air-filled flexible ball deforms and rebounds; inflation level and size affect bounce and handling.",
"Jigsaw":"Puzzle of interlocking pieces reconstructs one image or shape by matching edges and visual clues.",
"Kaleidoscope":"Mirrors inside a tube reflect colored pieces into repeated symmetrical patterns as the view changes.",
"Lego Brick":"Interlocking plastic construction brick uses studs and tubes to connect; small pieces require age-appropriate supervision.",
"Model Car":"Small-scale representation of a car; wheels may roll, but exact mechanism depends on the model.",
"Number Puzzle":"Puzzle uses numerals or quantities as matching clues, combining shape fitting with number recognition.",
"Origami":"Paper folding can become a play object or model through creases; it is paper craft, not a manufactured toy mechanism.",
"Puzzle":"Problem or object designed to be solved by matching, arranging, reasoning, or fitting pieces.",
"Quiz Game":"Question-and-answer game tests recall or reasoning; a missed answer is a chance to learn, not a judgment of the player.",
"Robot":"Toy or model robot represents a machine that can sense, compute, or move; not every robot toy is autonomous.",
"Scooter":"Wheeled ride-on platform steered by handlebars in common designs; helmet, suitable area, and supervision matter.",
"Teddy Bear":"Soft stuffed bear-shaped toy supports comfort or pretend play; loose eyes, seams, and stuffing must stay secure.",
"Uno Cards":"Commercial card-game deck uses colors, numbers, and action symbols; play follows its published rules rather than ordinary playing-card rules.",
"Velcro Ball":"Project toy uses hook-and-loop material so a light ball can stick to a matching target or mitt.",
"Wagon":"Low wheeled cart can carry toys or be pulled; riding rules depend on design and adult supervision.",
"Xylophone Toy":"Toy with bar-like keys can introduce pitch patterns; toy tuning may be approximate rather than concert-accurate.",
"Yarn Doll":"Figure made by wrapping and tying yarn; loose fibers or long strands require supervised craft/play.",
"Zoom Car":"Project label for a small toy car; do not invent a pull-back, battery, or friction motor unless the pictured model shows one.",
"Action Figure":"Small articulated character figure supports posing and pretend narratives; small accessories can be choking hazards.",
"Ball":"Round play object rolls or bounces depending material and inflation; size should fit the age and activity.",
"Excavator Toy":"Toy model represents an excavator with boom, stick, bucket, and tracked/wheeled base depending design.",
"Finger Puppet":"Small character fits over a finger for storytelling; size and detachable pieces must be age-appropriate.",
"Game Board":"Marked surface organizes spaces, paths, or zones for a game; rules give the marks their meaning.",
"Interlocking Blocks":"Building pieces connect through fitted shapes or studs; connection strength and geometry affect structures.",
"Jump Rope":"Rope turned for jumping games; clear space and supervised use prevent trips or wrapping around the body.",
"Kite":"Light frame/sail flies in wind on a line; use in open areas far from roads, storms, and power lines.",
"Letter Tiles":"Individual tiles display letters for sorting, spelling, or word play; they are movable symbols rather than fixed text.",
"Marble":"Small hard sphere rolls smoothly and can be used in games; its size creates a serious choking hazard for young children.",
"Octopus Toy":"Octopus-shaped toy is identified by form; material, seams, and detachable parts determine safe use.",
"Plush Bear":"Soft stuffed bear toy; secure seams and attached parts matter more than the exact fur texture.",
"Rattle":"Enclosed loose pieces or a moving part create sound when shaken; casing must stay intact so small contents cannot escape.",
"Unicycle":"Single-wheel ride-on cycle requires balance skill and protective equipment; it is not a preschool indoor riding toy.",
"Vehicle Toy":"Broad category for toy representations of transport; wheels, motors, scale, and function vary by model.",
"X-shaped Puzzle":"Puzzle target uses a clear X-shaped piece or outline; the X form is the identification clue.",
"Car Toy":"Toy representation of a car; rolling wheels are common, but propulsion method depends on the specific toy.",
"Doll":"Human- or character-shaped play figure supports caregiving and storytelling play; parts and accessories must be age-appropriate.",
"Hobby Horse":"Pretend horse toy, often a horse head on a stick or rocking form; clear space prevents collisions.",
"Nesting Blocks":"Graduated hollow blocks fit inside one another and can also stack, teaching size order and containment.",
"Quoits Ring":"Ring used in tossing games toward a peg or target; soft, age-appropriate rings reduce impact risk.",
"Toy Train":"Toy representation of railway vehicles; track, coupling, power, and wheel mechanisms depend on the set.",
"Wooden Blocks":"Solid wood construction pieces can stack and balance; smooth edges and non-toxic finishes matter.",
"Yo-yo":"Spool-like toy travels up and down a string through rotation; string length and clear space require supervision.",
"Zipper Toy Bag":"Bag with zipper stores toys and loose parts; storage helps keep small components together.",
"Stuffed Animal":"Soft fabric animal-shaped toy filled with stuffing; seams and attached features must remain secure.",
}
ACTIONS={"Marble":"Point only; show a tiny circle with fingers—no real marble for preschool play.","Jump Rope":"Air-draw one rope arc; do not wrap anything around the body.","Kite":"Trace a diamond in the air; name open-sky safety.","Scooter":"Point and mime holding handlebars while standing still.","Unicycle":"Point only; no balance stunt imitation.","Frisbee":"Air-trace a flat disc; no throwing indoors.","Yo-yo":"Move one empty hand gently down and up; no string around fingers or neck.","Yarn Doll":"Point and trace one yarn loop; keep long strands supervised.","Rattle":"Shake a closed empty fist softly; never open a real rattle.","Lego Brick":"Point to one brick; keep small pieces away from mouths.","Action Figure":"Pose two fingers; keep tiny accessories out of mouths."}
